import React, { Component } from "react";
import "./Homepage.css";
import f from "./"
export default class Homepage extends Component {
  constructor(props) {
    super(props);
    this.state = {
      currentIndex: 0,
      homepage: null,
      imageBack:[]
    };
  }

  componentDidMount() {

    fetch(`http://localhost:3001/pages/5`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({})
    }) 
    .then(response => response.json())
    .then(data => {

      const gallery = [];

      if (data.Img1) gallery.push(data.Img1);
      if (data.Img2) gallery.push(data.Img2);
      if (data.Img3) gallery.push(data.Img3);

      this.setState({imageBack:gallery, homepage: data });
    })
    .catch(error => console.error('Error fetching data:', error));
  }

  goToPrevious = () => {
    debugger
    this.setState(prevState=>({
      currentIndex:(prevState.currentIndex-1+prevState.imageBack.length) % prevState.imageBack.length
    }))
    // const { currentIndex, homepage } = this.state;
    // const isFirstSlide = currentIndex === 0;
    // const newIndex = isFirstSlide ? homepage.gallery?.length - 1 : currentIndex - 1;
    // this.setState({ currentIndex: newIndex });
  };

  goToNext = () => {
    this.setState(prevState=>({

      currentIndex:(prevState.currentIndex+1) % prevState.imageBack.length,
    }))
    // const { currentIndex, homepage } = this.state;
    // const isLastSlide = currentIndex === homepage.gallery?.length - 1;
    // const newIndex = isLastSlide ? 0 : currentIndex + 1;
    // this.setState({ currentIndex: newIndex });

};

  render() {
    const { currentIndex, homepage , imageBack} = this.state;
    if (!homepage) return null;
    console.log("image",imageBack)
    const homeGallery = homepage.gallery;
    const arrowLeftDisplay = currentIndex === 0 ? "none" : "block";
    const arrowRightDisplay = currentIndex === homeGallery?.length - 1 ? "none" : "block";

    return (
      <div className="gallery">
        <button onClick={this.goToPrevious} className="arrow left-arrow" style={{ display: arrowLeftDisplay }}>
          ❮
        </button>

        <div className="slider">
          <div className="slider-inner" style={{ transform: `translateX(-${currentIndex * 100}%)` }}>
            {imageBack?.map((image, index) => {
              console.log(index)
              return(
        <div className="slide" key={index}>
                <div className="image" style={{ backgroundImage: `url(${image})` }}></div>
                <a href="./Service">
                  <button className="gallery-button" >Find my pet</button>
                </a>
              </div>
              )
            }

            )}
          </div>
        </div>

        <button onClick={this.goToNext} className="arrow right-arrow" style={{ display: arrowRightDisplay }}>
          ❯
        </button>

        <div className="squares-container">
          <div className="square"></div>
          <div className="square"></div>
          <div className="square"></div>
          <div className="square"></div>
        </div>
      </div>
    );
  }
}
